```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int lo = 10, hi = 20;
    int maxLen = 0, maxStart = 0, maxSum = 0;
    for (int i = 0; i < (int)dane.size(); i++) {
        int suma = 0;
        for (int j = i; j < (int)dane.size(); j++) {
            suma += dane[j];
            if (suma > hi) break;
            int len = j - i + 1;
            if (suma >= lo && len > maxLen) {
                maxLen = len;
                maxStart = i;
                maxSum = suma;
            }
        }
    }
    cout << "Najdluzszy podciag ze suma w [" << lo << ", " << hi << "]: " << maxLen << " elementow" << endl;
    cout << "Poczatek: pozycja " << maxStart + 1 << endl;
    cout << "Elementy:";
    for (int i = maxStart; i < maxStart + maxLen; i++) {
        cout << " " << dane[i];
    }
    cout << endl;
    cout << "Suma: " << maxSum << endl;
    return 0;
}
```

